<?php
require 'page-guard.php';require '../config/db_conn.php';require 'components.php';$section=$_SESSION['teacher-section'];$studentQuery=$conn->prepare('SELECT STUDENT_ID,STUDENT_NAME FROM students WHERE SECTION=? ORDER BY STUDENT_NAME');$studentQuery->bind_param('s',$section);$studentQuery->execute();$studentResult=$studentQuery->get_result();$studentOptions=[];while($student=$studentResult->fetch_assoc())$studentOptions[]=['value'=>$student['STUDENT_ID'],'label'=>$student['STUDENT_NAME'].' · '.$student['STUDENT_ID']];teacherHead('Attendance');teacherShell('Attendance records'); ?>
<section class="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap items-end justify-between gap-4 border-b border-slate-100 pb-5"><div><h2 class="text-2xl font-black text-slate-900"><?= htmlspecialchars($section) ?></h2><p class="mt-1 text-slate-500">View and export your section attendance.</p></div><a id="export-link" href="export-attendance.php?date=<?= date('Y-m-d') ?>" class="rounded-xl bg-emerald-600 px-4 py-3 text-sm font-bold text-white hover:bg-emerald-700">Export spreadsheet</a></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="relative text-sm font-bold text-slate-700">Student<div class="relative mt-2"><input id="student-filter" class="w-full rounded-xl border border-slate-300 px-4 py-3" placeholder="Search by student name or ID" autocomplete="off"><div id="student-options" class="absolute inset-x-0 z-20 mt-2 hidden max-h-56 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl"></div></div></label><label class="text-sm font-bold text-slate-700">Date<input id="date-filter" type="date" value="<?= date('Y-m-d') ?>" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"></label></div><div class="mt-6 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3">Student ID</th><th class="px-4 py-3">Name</th><th class="px-4 py-3">Date</th><th class="px-4 py-3">Time in</th><th class="px-4 py-3">Status</th></tr></thead><tbody id="attendance-rows" class="divide-y divide-slate-100"></tbody></table></div></section><script>const studentInput=document.getElementById('student-filter'),studentMenu=document.getElementById('student-options'),date=document.getElementById('date-filter'),rows=document.getElementById('attendance-rows'),exportLink=document.getElementById('export-link'),studentItems=<?= json_encode($studentOptions) ?>;let studentValue='';function drawStudents(){const query=studentInput.value.toLowerCase();studentMenu.innerHTML='';studentItems.filter(item=>item.label.toLowerCase().includes(query)).forEach(item=>{const button=document.createElement('button');button.type='button';button.className='block w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-100';button.textContent=item.label;button.onclick=()=>{studentInput.value=item.label;studentValue=item.value;studentMenu.classList.add('hidden');update()};studentMenu.appendChild(button)});studentMenu.classList.toggle('hidden',!studentMenu.children.length)}function update(){const params=new URLSearchParams({student:studentValue,date:date.value});fetch('get-attendance.php?'+params).then(r=>r.text()).then(html=>rows.innerHTML=html).catch(()=>rows.innerHTML='<tr><td colspan="5" class="px-4 py-8 text-center text-rose-600">Could not load records.</td></tr>');exportLink.href='export-attendance.php?'+params}studentInput.onfocus=drawStudents;studentInput.oninput=()=>{studentValue='';drawStudents()};studentInput.onkeydown=event=>{if(event.key==='Escape')studentMenu.classList.add('hidden')};date.onchange=update;document.addEventListener('click',event=>{if(!event.target.closest('.relative'))studentMenu.classList.add('hidden')});update();setInterval(update,10000)</script><?php teacherFoot(); ?>